/**
 * Soobin idle + walk textures (normal + holding paper/pen).
 * Generated by: python scripts/make_soobin_walk_frames.py
 */

export const SOOBIN_DIRS = /** @type {const} */ (['down', 'up', 'left', 'right'])

/**
 * @param {'normal' | 'holding'} variant
 */
export function getSoobinVariant(variant) {
  const prefix = variant === 'holding' ? 'soobin-holding' : 'soobin'
  const idle = {}
  const animKeys = {}
  const walkFrameKey = (dir, n) => `${prefix}-${dir}-${n}`
  const walkFramePath = (dir, n) => `assets/characters/soobin/${prefix}-${dir}-${n}.png`

  for (const dir of SOOBIN_DIRS) {
    idle[dir] = {
      key: `${prefix}-${dir}`,
      path: `assets/characters/soobin/${prefix}-${dir}.png`,
    }
    animKeys[dir] = `${prefix}-walk-${dir}`
  }

  return {
    variant,
    prefix,
    idle,
    animKeys,
    frameRate: 10,
    walkFrameKey,
    walkFramePath,
  }
}

export const SOOBIN_NORMAL = getSoobinVariant('normal')
export const SOOBIN_HOLDING = getSoobinVariant('holding')

/**
 * @param {Phaser.Scene} scene
 * @param {ReturnType<typeof getSoobinVariant>} pack
 */
export function preloadSoobinVariant(scene, pack) {
  for (const dir of SOOBIN_DIRS) {
    scene.load.image(pack.idle[dir].key, pack.idle[dir].path)
    for (const n of /** @type {const} */ ([1, 2, 3])) {
      scene.load.image(pack.walkFrameKey(dir, n), pack.walkFramePath(dir, n))
    }
  }
}

/**
 * @param {Phaser.Scene} scene
 * @param {ReturnType<typeof getSoobinVariant>} pack
 */
export function ensureSoobinWalkAnims(scene, pack) {
  for (const dir of SOOBIN_DIRS) {
    const key = pack.animKeys[dir]
    if (scene.anims.exists(key)) scene.anims.remove(key)
    scene.anims.create({
      key,
      frames: [
        { key: pack.walkFrameKey(dir, 1) },
        { key: pack.walkFrameKey(dir, 2) },
        { key: pack.walkFrameKey(dir, 3) },
        { key: pack.walkFrameKey(dir, 2) },
      ],
      frameRate: pack.frameRate,
      repeat: -1,
    })
  }
}

/**
 * @param {Phaser.Scene} scene
 * @param {ReturnType<typeof getSoobinVariant>} pack
 */
export function applySoobinNearestFilter(scene, pack) {
  for (const dir of SOOBIN_DIRS) {
    scene.textures.get(pack.idle[dir].key)?.setFilter(Phaser.Textures.FilterMode.NEAREST)
    for (const n of /** @type {const} */ ([1, 2, 3])) {
      scene.textures
        .get(pack.walkFrameKey(dir, n))
        ?.setFilter(Phaser.Textures.FilterMode.NEAREST)
    }
  }
}
